def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Solid non-background rows and columns are the dividers.
    divider_rows = [
        r for r, row in enumerate(grid)
        if len(set(row)) == 1 and row[0] != background
    ]
