        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def intervals(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_regions = intervals(h, divider_rows)
    col_regions = intervals(w, divider_cols)

    # Find the region containing the source pattern.
    source = None
