            pixels = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != background
            ]
            if len(pixels) > best_count:
                best_count = len(pixels)
                source = (ri, ci, pixels)

    out = [row[:] for row in grid]
    if source is None:
